<?php
declare(strict_types=1);
namespace App;
use PDO;
final class RoleService {
    public static function admin():void {Auth::requirePermission('identity.manage');if((Auth::user()['role_id']??null)!=='admin')throw new \RuntimeException('Управление ролями доступно только Администратору.',403);}
    public static function role(string $id):array {$q=DB::pdo()->prepare('SELECT r.*,rp.kind workflow_kind FROM roles r LEFT JOIN role_profiles rp ON rp.role_id=r.id WHERE r.id=?');$q->execute([$id]);return $q->fetch()?:throw new \RuntimeException('Роль не найдена.',404);}
    public static function grants(array $role):array {if(empty($role['id']))return array_fill_keys(array_keys(PagePolicy::catalog()),0);$out=[];foreach(PagePolicy::catalog()as $key=>$page)$out[$key]=PagePolicy::levelForRole($role['id'],$role['id']==='admin'?'admin':($role['workflow_kind']??'viewer'),(bool)$role['grants_configured'],$key);return $out;}
    public static function save(?string $id,array $input):string {
        self::admin();return DB::transaction(function(PDO $p)use($id,$input):string {$p->query('SELECT id FROM identity_write_guard WHERE id=1 FOR UPDATE')->fetchColumn();$old=$id?self::role($id):null;if($old&&(int)$old['revision']!==(int)($input['expected_revision']??0))throw new \RuntimeException('Данные уже изменены в другом окне. Обновите страницу и повторите изменение.',409);$name=$id==='admin'?$old['name']:trim((string)($input['name']??''));$description=trim((string)($input['description']??''));if($name===''||mb_strlen($name)>100||mb_strlen($description)>10000)throw new \RuntimeException('Проверьте название и описание роли.',422);$q=$p->prepare('SELECT id FROM roles WHERE name=? AND id<>?');$q->execute([$name,$id??'']);if($q->fetchColumn())throw new \RuntimeException('Роль с таким названием уже есть.',422);
            $posted=$input['grants']??[];if(!is_array($posted))throw new \RuntimeException('Некорректная матрица прав.',422);$catalog=PagePolicy::catalog();if(array_diff(array_keys($posted),array_keys($catalog)))throw new \RuntimeException('Неизвестная страница в матрице прав.',422);$grants=[];foreach($catalog as $key=>$page){$value=$posted[$key]??'0';if(!in_array((string)$value,['0','1','2'],true))throw new \RuntimeException('Укажите нет доступа, чтение или чтение и редактирование.',422);$grants[$key]=(int)$value;}
            if($old)$p->prepare('UPDATE roles SET name=?,description=?,revision=revision+1,grants_configured=? WHERE id=?')->execute([$name,$description,$id==='admin'?0:1,$id]);else{$id='role-'.bin2hex(random_bytes(10));$p->prepare('INSERT INTO roles(id,name,description,grants_configured) VALUES(?,?,?,1)')->execute([$id,$name,$description]);}
            if($id!=='admin'){$p->prepare('DELETE FROM role_page_grants WHERE role_id=?')->execute([$id]);$q=$p->prepare('INSERT INTO role_page_grants(role_id,page_key,level) VALUES(?,?,?)');foreach($grants as $key=>$level)$q->execute([$id,$key,$level]);$permissions=[];$kind=$old['workflow_kind']??null;foreach($grants as $key=>$level){if(!$level)continue;$page=$catalog[$key];$permissions[$page['read']]=true;if($level===2){if(str_starts_with($key,'rental.')){$permission=match($kind){'manager'=>'rental.write','lawyer'=>'rental.approve.legal','accountant'=>'finance.write','director'=>'rental.approve.executive',default=>null};if($permission)$permissions[$permission]=true;}else foreach($page['edit']as $permission)$permissions[$permission]=true;}}
                $p->prepare("DELETE FROM role_permissions WHERE role_id=? AND permission_key IN ('rental.read','rental.write','rental.approve.legal','finance.write','rental.approve.executive','integrations.read','integrations.write','messaging.read','messaging.write','messaging.send','premises.write','identity.permissions')")->execute([$id]);$q=$p->prepare('INSERT IGNORE INTO role_permissions(role_id,permission_key) VALUES(?,?)');foreach(array_keys($permissions)as $permission)$q->execute([$id,$permission]);
            }
            Audit::record($old?'role.update':'role.create','role',$id,$old?['name'=>$old['name'],'revision'=>$old['revision']]:null,['name'=>$name,'revision'=>$old?(int)$old['revision']+1:1]);return $id;
        });
    }
    public static function delete(string $id,int $revision):void {
        self::admin();DB::transaction(function(PDO $p)use($id,$revision):void {$p->query('SELECT id FROM identity_write_guard WHERE id=1 FOR UPDATE')->fetchColumn();$role=self::role($id);if((int)$role['revision']!==$revision)throw new \RuntimeException('Данные уже изменены в другом окне. Обновите страницу и повторите изменение.',409);if($id==='admin')throw new \RuntimeException('Роль Администратор нельзя удалить.',422);$q=$p->prepare('SELECT COUNT(*) FROM users WHERE role=?');$q->execute([$id]);if($q->fetchColumn())throw new \RuntimeException('Сначала назначьте пользователям этой роли другую роль.',422);if($role['workflow_kind']!==null)throw new \RuntimeException('Роль связана с рабочим процессом аренды.',422);$p->prepare('DELETE FROM role_permissions WHERE role_id=?')->execute([$id]);$p->prepare('DELETE FROM role_page_grants WHERE role_id=?')->execute([$id]);$p->prepare('DELETE FROM roles WHERE id=?')->execute([$id]);Audit::record('role.delete','role',$id,['name'=>$role['name']],null);});
    }
}
